# -*- coding: utf-8 -*-
import json, os, re
TID = 't1124'
with open(f'data/baihua-tasks/{TID}.json', encoding='utf-8') as f: task=json.load(f)
TITLE = task['title']; TRANSLATOR = task['translator']
INTRO = '本儀軌全一卷，唐代不空奉詔譯，出自《大正藏》密教部，是普賢（金剛薩埵）「身口意金剛」念誦法的略瑜伽儀軌。內容依序為：擇處結跏、淨三業、觀如來相好供養、受律儀戒；結金剛掌、金剛縛、金剛遍入、金剛拳、金剛薩埵、素囉多大誓真實、勝三世忿怒、蓮華族、金剛界（五佛冠）、灌頂、鬘、被甲、金剛輪、警覺聖眾等諸印；安立四門菩薩（鉤索鎖鈴）與內外供養十六尊，誦一百八名讚及普賢菩薩讚；末說滿月夜念誦、普賢入身、成就威德利生等，為密教瑜伽念誦法的集成。'
TITLES = ["译者题名·说普贤金刚念诵法·行者为缘","择处坐法·净三业密语","观如来相好·运想供养·四礼印契","持金刚三么耶印·发露说罪等","思惟发愿密语·金刚掌印","金刚掌印功德·金刚缚印·拍胸","拍心密语·入曼荼罗·金刚遍入印","遍入印功德·金刚拳印","金刚拳印功德·金刚萨埵印","素囉多大誓真实印·观身成普贤","大誓真实密语·胜三世忿怒金刚三摩地","辟除密语","金刚智火焚杂染·莲华族三摩耶印","莲华族印·定印·观虚空诸佛","定印功德·通达心密语","九种缘生三摩地智·菩提心观","菩提心密语·胸中月轮·五钴杵","心成金刚·观身如五钴杵·诸佛入杵","三业成金刚·观自身如普贤菩萨","素囉多金刚印·金刚界印（五佛冠印）","金刚界印密语·灌顶印·鬘印","被甲印","被甲密语·欢喜拍印·金刚轮曼荼罗印","金刚轮印·警觉一切圣众印","警觉印功德·四门菩萨（钩索锁）","四门菩萨（铃）·钩印","索印","锁印·铃印·本尊百八名赞","奉请密语（一）","奉请密语（二）","奉请密语（三）","奉请密语（四）·钩索锁铃配字","钩索锁铃四印用法·閼伽印","捧閼伽奉獻·閼伽密语","閼伽功德·外供养四尊（戏笑歌舞）","四外供养印（一）·歌·舞","嬉戏印·笑印·歌印","歌印密语·舞印","焚香印·春金刚菩萨印","春金刚·秋金刚灯印","秋金刚·金刚云菩萨印","坛中月轮普贤·金刚慢印·欲金刚等四尊","四尊（续）·五尊住羯磨三摩地印","五尊密语（一）·金刚·计里计罗·爱","慢菩萨密语·十七尊总观·普贤菩萨赞","普贤菩萨赞（一）","普贤菩萨赞（二）·四句配四印","大乘不空三昧耶真实密语·念诵仪则","疲倦解印·满月夜念诵·普贤入身","成威德·神通利生·成毘卢遮那身"]
JIE = ["開府儀同三司、特進試鴻臚卿、肅國公、食邑三千戶、賜紫、贈司空、謚大鑒正號、大廣智、大興善寺三藏沙門不空奉詔譯。說普賢菩薩身口意金剛念誦法：修此法等同金剛薩埵；行者須住勝解行地、曾入金剛界大曼荼羅、受菩提心戒，於諸有情有大悲愍拔濟安樂心，不惜身命，念念常懷得普賢菩薩身。","於山間阿蘭若、或精室、伽藍、宅舍建立道場，面向東或西隨取穩便，端身結跏趺坐（全跏、普賢跏或隨意坐），心遍緣一切有情界、令有情三業清淨，誦密語。","次觀如來相好圓備、運心想供養，以天妙塗香、花鬘、香、燈燭、飲食、種種讚歎，依四種禮印契密語禮四方如來、捨身供養，則成受三世無礙智律儀戒；則起，右膝著地，結持金剛三麼耶印，當心誦、於頂上散。","由結此印誦密語，則成遍禮供養承事一切如來。次應發露說罪、隨喜、勸請、迴向、發願已，則結跏趺坐，作是思惟：「願一切有情獲出世無上悉地成就。」","誦思惟發願密語；次結金剛掌印，誦密語三遍。","由結金剛掌印及誦密語，所修瑜伽相應門悉地皆成就；結金剛縛印，由結使皆得解脫、十波羅蜜頓得圓滿。次即以縛印三掣拍胸間。","由結此印及誦密語，當入曼荼羅，阿闍梨所引入，金剛薩埵三業金剛令入弟子心，自性金剛智令得發動顯現。次結金剛遍入印（即前金剛縛、二大指入掌安於無名指間）。","由結此印，三業金剛於身中作大阿吠奢（遍入），獲大神驗威德。次以准前印、二頭指各屈拄二大指背，即成金剛拳印。","由結此印，令三業金剛堅住不散失。次以前金剛縛印合豎二中指，是金剛薩埵印；由結此印，行者當住普賢菩薩三摩地、坐於月輪，令身色相光明圓備。","次結素囉多大誓真實印（以縛印，二大指二小指各以指頭相拄如獨股杵，二中指入掌豎合拄心）；作是思惟「我身既成普賢菩薩」，發此心時成就無邊解脫，觀一切有情自他無別、同體大悲。","誦大誓真實密語；次應住勝三世忿怒金剛三摩地（立印，四面八臂威德赫奕、光明熾盛如劫燒，左腳踏摩醯首羅、右腳踏烏摩）；即以二手金剛拳辟除諸魔、右旋成結界。","誦勝三世辟除密語；諸佛菩薩尚不違越，何況三界中作障者。即以印印心額喉頂四處。","由結此印誦密語三密相應，阿賴耶識中所有雜染種子以此金剛智火焚燒悉盡，一切外障不能為障難。次結蓮華族三摩耶印。","以二手金剛縛、合豎二大指及二小指、以印安於口，想自身同金剛法菩薩；由結此印，所修三摩地瑜伽悉皆現前。次結定印，遍觀虛空諸佛猶如胡麻，誦密語。","由結此印誦密語，滅一切障、獲得安樂悅意、超魔境，即同諸佛得一切世天供養。即誦通達心密語。","次入九種緣生三摩地智，觀一切法如幻、如陽焰、如夢、如影像、如聲響、如光影、如水月、如變化、如虛空；作是觀已，是心於染於淨通達無礙、猶若虛空。次應入菩提心觀中誦密語。","誦菩提心密語；由結此印，則於身中當胸臆間觀圓滿月皎潔清涼，誦通達菩提心密語已，得心水澄淨、菩提心月影現於中；於此滿月上觀五鈷金剛杵了了分明，誦密語。","由作如是觀誦此密語，是心成如金剛。次觀身如五鈷金剛杵，誦密語；次觀遍滿虛空中佛悉來入金剛杵中合為一體。","由作如是觀智並誦密語，行者三業成如金剛。行者當觀自身如普賢菩薩——戴五佛冠、身如水精月色，右手持五鈷金剛杵、左手持金剛鈴，身處滿月輪了了分明，誦密語。","次用素囉多金剛印（結金剛縛、以右大母指入左虎口）；以此印加持心額喉頂。次二手金剛縛、豎二中指屈上節如劍、二頭指各屈輔中指、二大指如結跏即成，是名金剛界印，亦名五佛冠印。","誦金剛界印密語；次結灌頂印置於頂上（同前印），誦密語；次以二手作金剛拳當額如繫鬘繒，次腦後亦如前繫已、從小指散下如垂引繒帶勢。","誦密語；次結被甲印——二手金剛拳展二頭指，於指端想「唵砧」二字，便以二指當心相繞三遍，次背後卻至臍、二膝，又至臍，次腰卻至心、左右肩頸，次頂、後額，腦後結拳如繫甲勢。","誦被甲密語；次二手旋拳如舞勢、妙拍一遍令歡喜，誦密語。次結金剛輪曼荼羅印。","二手金剛拳、二頭指二小指互相鉤即成金剛輪印，印地及身五處，誦密語。次結警覺一切聖眾印（二手交臂右押左彈指，每誦一遍一彈指，令滿四遍），誦密語。","由作此印，普賢菩薩及一切眷屬應時雲集在於空中。次結四門菩薩印儀：東門金剛鉤菩薩（青色）居曼荼羅中、南門金剛索菩薩（黃色，持索為印）、西門金剛鎖菩薩（赤色，持鎖為印）。","北門金剛鈴菩薩（綠色，持鈴為印）；此四菩薩各具五佛冠鬘、種種嚴麗以為莊嚴。次結鉤印（二手金剛拳、二小指反相鉤、直豎左頭指、屈右頭指上下往來），誦密語。","次不解前印，改二頭指頭相拄如鐶，是索印，誦密語。","次以前印，二頭指二大指互相交、頭相捻、屈其臂，是鎖印；次如前鎖印、二大指入掌搖動即成（鈴印）。次誦本尊菩薩一百八名讚，誦已則結金剛薩埵大誓真實印並誦密語，請聖眾降曼荼羅中。","誦金剛薩埵奉請密語（梵音音譯、原字保留、音注略去），起句。","續錄奉請密語。","續錄奉請密語。","奉請密語以「弱吽鑁斛」作結。由結印誦密語，能警覺普賢菩薩並諸聖眾眷屬歡悅，不越本誓來降道場。","此印及密語能召引入縛令喜悅：誦至「弱」字，掌中二指如鉤來去；至「吽」字，屈如環則成索；至「鑁」字，交結則名鎖；至「斛」字，如鈴搖動能悅諸聖，或誦三遍或四遍。次結閼伽印（二手金剛掌、二中指頭相合、二頭指在中指後如鉤形、二大指各捻二頭指根下）。","以印捧閼伽器、當額奉獻。若道場中先無閼伽，但改二大指相交即成，名閼伽印；想八功德水浴諸聖尊足，誦密語。","由獻閼伽故，能洗滌無始煩惱塵垢、速獲身口意清淨。次結外供養諸尊：東南喜戲菩薩（二金剛拳當於心）。","西南金剛笑菩薩（二拳各在傍向後散勢）；西北金剛歌菩薩（左手作拳、豎臂展頭指向身持箜篌為印，右作彈弦勢）；東北金剛舞菩薩（二拳旋轉結舞印）；此四尊服形皆作金色。","如初嬉戲印，以二拳遶心左右轉，誦密語；次結笑印（如前印安口傍、翻掌向外、從小指漸開、各向後散、住笑容），誦密語；次以右手作拳、豎頭指屈臂向身如箜篌，右拳豎頭指作彈弦勢，是為歌印。","誦歌印密語；次二拳從心旋轉舞、漸上至頂、合掌便散，是舞印，誦密語。次結雲金剛菩薩焚香印。","以二拳相並、下擲即成焚香印；想此尊在壇內院東南隅，形服皆黑、持香爐以為印，誦密語。次以二拳初如舞、便以二拳相並上如散華勢，是春金剛菩薩印。","當想春金剛尊居內院西南隅，色服俱白、持華，誦密語。次結秋金剛菩薩燈印（二拳並豎二大指）；想此尊居內院西北隅，形服皆赤、持燈為印。","誦秋金剛密語；次結金剛雲菩薩印（並覆二拳摩其胸、兩向散）；想此尊居內院東北隅，形服皆綠色、持塗香器，誦密語。","次於曼荼羅中位想圓滿月，於月輪中有普賢菩薩、住金剛慢印。次於大聖前想欲金剛（形服色赤、衣冠鬘瓔珞莊嚴、目瞻大聖、住金剛弓箭印）。","次於大聖右想計里計羅尊（色白、二金剛拳交臂、住抱印）；次於大聖後想愛金剛（形服皆青、豎左臂執摩竭幢、右手承其肘共持幢）；於大聖左邊想金剛慢尊（形服皆黃、二金剛拳各安胯、頭向左少低）。此五尊皆住羯磨三摩地印。","誦金剛密語；次誦計里計羅尊密語；次誦金剛愛密語。","誦慢菩薩密語。以上十七尊聖眾形色、衣服、花座、月輪中，及己身住大印，皆有聖尊眷屬圍繞，皆須明了。次當誦普賢菩薩讚。","誦普賢菩薩讚，起句。","誦第一句讚當結欲金剛羯磨印；次誦第二句結計里吉羅金剛羯磨印；次第三句結愛金剛羯磨印；第四句結慢金剛羯磨印，則成四種歌詠。四種舞印，誦讚時入大三摩地用之。","次誦大乘不空三昧耶真實密語。住大印，等同普賢菩薩。若欲成就本尊，應一月念誦，每日四時無限數念誦。","若疲倦，解印、全身金剛合掌作禮，以此為憩息令心不疲厭。其滿月夜結大印，一夜念誦至於晨朝，普賢菩薩來、身光如月輪，抱其行者自身入遍支分；其行者身等同普賢——五佛頭冠、身著天妙瓔珞華鬘、身口意如金剛薩埵。","所有親族見彼人成如是威德，皆生驚愕、恭敬禮拜。彼人常在自家作大神通，亦作佛身現大神通、亦現三世勝金剛身，調伏難調者悉皆調伏，隨意騰空、自在往無量世界供養諸佛，受天妙五欲樂，壽命盡虛，利樂無邊有情成大利益，成毘盧遮那佛身。"]

texts=[t['original_preview'] for t in task['translations']]
full=''; ranges=[]
for t in texts:
    a=len(full); full+=t; ranges.append((a,len(full)))

def is_curse(s):
    if re.search(r'（[^）]*）', s): return True
    if '二合' in s or '三合' in s: return True
    if len(s)<=30 and not re.search(r'[，。！？；：「」]', s): return True
    return False

flag=[False]*len(full)
for m in re.finditer(r'「([^」]*)」', full):
    if is_curse(m.group(1)):
        for k in range(m.start(), m.end()): flag[k]=True

def render(a,b):
    out=[]; i=a; inc=False
    while i<b:
        c=full[i]; f=flag[i]
        if f:
            if not inc: out.append('⟪'); inc=True
            if c=='「' or c=='」':
                i+=1; continue
            if c=='（':
                j=i+1
                while j<b and full[j]!='）': j+=1
                i=j+1; continue
            out.append(c); i+=1
        else:
            if inc: out.append('⟫'); inc=False
            out.append(c); i+=1
    if inc: out.append('⟫')
    return ''.join(out)

MODS=[]
for i,(a,b) in enumerate(ranges):
    body=re.sub(r'[\r\n\t ]+','',render(a,b))
    MODS.append("【%s】%s【义解】%s" % (TITLES[i], body, JIE[i]))

assert len(MODS)==len(task['translations'])==50, len(MODS)
trans=[]
for i,mod in enumerate(MODS):
    mm=re.match(r'(【[^】]+】)',mod); sec=mm.group(1) if mm else f"【段{i+1}】"
    trans.append({"section":sec,"original_preview":task['translations'][i]['original_preview'],"modern":mod})
out={"id":TID,"title":TITLE,"translator":TRANSLATOR,"mode":"白話精譯","intro":INTRO,"sutraPath":task['sutraPath'],"translations":trans}
with open(f'data/modern-translation/{TID}.json','w',encoding='utf-8') as f:
    json.dump(out,f,ensure_ascii=False,indent=2)
print(f'Wrote {TID} {len(trans)}')
